{"name":"getConnectionHandler","qualified_name":"C-benchmark-codebase-memory-nest.packages.websockets.web-sockets-controller.WebSocketsController.getConnectionHandler","label":"Method","file_path":"C:/benchmark/codebase-memory/nest/packages/websockets/web-sockets-controller.ts","start_line":246,"end_line":265,"source":"  public getConnectionHandler(
    context: WebSocketsController,
    instance: NestGateway,
    subscribersMap: MessageMappingProperties[],
    disconnect: Subject<any>,
    connection: Subject<any>,
  ) {
    const adapter = this.config.getIoAdapter();
    return (...args: unknown[]) => {
      const [client] = args;
      connection.next(args);
      context.subscribeMessages(subscribersMap, client, instance);

      const disconnectHook = adapter.bindClientDisconnect;
      disconnectHook &&
        disconnectHook.call(adapter, client, (reason?: string) =>
          disconnect.next({ client, reason }),
        );
    };
  }
